INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·后唐纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e00f3e22/content/books/zizhi-tongjian/vol-276/year-0927/part-04/sources/library/tongjian-276-late-927-opening/source.txt", "note": "《资治通鉴》后唐纪五，段落 zizhi-tongjian-a63549944a71-p003281；电子底本待考，分段待核", "id": "7e3cc22f-28c2-55be-a24e-2143979e3bbe"}, {"title": "资治通鉴·后唐纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f890926e/content/books/zizhi-tongjian/vol-276/year-0928/part-02/sources/library/tongjian-276-salt-wars/source.txt", "note": "《资治通鉴》后唐纪五，段落 zizhi-tongjian-a63549944a71-p003283；电子底本待考，分段待核", "id": "e9eb585d-6322-5c10-80f9-2329cef14bff"}, {"title": "资治通鉴·后唐纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/86b40c48/content/books/zizhi-tongjian/vol-276/year-0928/part-05/sources/library/tongjian-276-late-summer/source.txt", "note": "《资治通鉴》后唐纪五，段落 zizhi-tongjian-a63549944a71-p003285；电子底本待考，分段待核", "id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"title": "新五代史·卷三十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/db4b82d4/content/books/zizhi-tongjian/vol-276/year-0928/part-04/sources/library/xinwudaishi-039-wangdu-dingzhou/source.txt", "note": "《新五代史》卷三十九，段落 xin-wudaishi-b08f244b9241-p001376；EPUB电子本，纸本及异文待核", "id": "d60aac22-2dfd-5717-aa0e-d37624d22cdc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孔循", "aliases": ["赵殷衡"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "孔循是孔氏的父亲。《新五代史》孔皇后传概述他曾任横海军节度使，没有在这里确定任职年份。", "biography": null, "status": "draft", "id": "cbc4feeb-706c-5478-8f90-6130e12ed543"}, {"name": "安重诲", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安重诲曾任后唐枢密使兼中书令，后调任护国节度使。931年闰五月退休后，李从璋接任护国节度使，在河中将他和妻子张氏杀死。朝廷随后列举罪名，并处死他的二子。", "biography": null, "status": "draft", "id": "ce1aed16-1e3c-550a-954b-f37ff4743d0c"}, {"name": "和昭训", "aliases": ["和昭訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "和昭训是王都的亲信。王都担心被调离藩镇时，他劝王都谋求自保。", "biography": null, "status": "draft", "id": "397478dd-f587-584b-90e5-3ff921948933"}, {"name": "王都", "aliases": ["刘云郎", "劉雲郎", "云郎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王都是定州统治者。929年定州陷落时与家族自焚；《旧五代史》还记其四子一弟后来被处刑，家族范围的不同记述分别保留。", "biography": null, "status": "draft", "id": "e990d522-e16a-5709-b3a3-fd6ccf95796b"}, {"name": "袁诠", "aliases": ["袁詮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "袁诠曾任楚国六军使。932年马希声去世后，与潘约等到朗州迎立马希范。", "biography": null, "status": "draft", "id": "7d2cfb56-e9ac-5d69-80a4-c6e4af7c4d87"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "马殷是楚国君主，907年获后梁封为楚王。《资治通鉴》记931年十二月葬于衡阳；《新五代史》作上潢，地点差异分别保留。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "王环", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王环任楚国六军副使。929年四月，在石首击败荆南军。", "biography": null, "status": "draft", "id": "6a6bb82a-8b0a-5492-a34a-772c01702860"}, {"name": "马希瞻", "aliases": ["馬希瞻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希瞻曾任楚国监军，随袁诠、王环率水军进攻荆南，在刘郎洑伏藏战舰，从侧面击败荆南军。", "biography": null, "status": "draft", "id": "3df1a631-6ec2-59fc-b5c8-028ed5fefc6c"}, {"name": "许德勋", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "许德勋任楚国右丞相。928年率水军击败吴军，俘获苗璘、王彦章；两人获释时，他告诫吴国须等楚王诸子争位才有可乘之机。", "biography": null, "status": "draft", "id": "22c59d0c-1661-5bcc-b43e-84d97c1ecda4"}, {"name": "冯赟", "aliases": ["馮贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯赟是太原人，曾任客省使、北都副留守。《资治通鉴》在934年三月戊辰条下记他被安从进杀害、家族被诛灭；《新五代史》在丁卯记他被杀，日期差异保留。", "biography": null, "status": "draft", "id": "2fecae8c-9a43-5dd2-bc47-db5c33c3188f"}, {"name": "李从荣", "aliases": ["李從榮", "从荣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李从荣是李嗣源的儿子，曾获任天雄节度使、同平章事，并任邺都留守。《资治通鉴》回顾他曾忌妒李从厚，这里说的是此前往事。", "biography": null, "status": "draft", "id": "87795090-8fc2-547d-a3a4-329b992a57f3"}, {"name": "杨思权", "aliases": ["楊思權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨思权是新平人，曾由夹马指挥使获任步军都指挥使，辅佐李从荣。后来任羽林军使，934年五月戊申获任静难节度使。", "biography": null, "status": "draft", "id": "dd63d02d-f660-5b3d-a323-acb6a441dbc3"}, {"name": "武从谏", "aliases": ["武從諫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武从谏是赵德钧的牙将。928年奉命率骑兵截击契丹败军，分守险要，俘获惕隐等人。", "biography": null, "status": "draft", "id": "6f5a738d-7e2a-5b28-8a99-c599caa1e5c7"}, {"name": "赵德钧", "aliases": ["趙德鈞", "李绍斌", "李紹斌"], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "赵德钧曾率兵救援泽州，尚未抵达时，泽州已经失陷。", "biography": null, "status": "draft", "id": "cfda6466-f577-56a2-8851-65b57edb7d3e"}, {"name": "郑季璘", "aliases": ["鄭季璘"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郑季璘是王都部下的指挥使。《新五代史》记他与杜弘寿率军迎接契丹，被王晏球击败俘获；未据杜弘寿被杀的句子推定他也同死。", "biography": null, "status": "draft", "id": "eee27a95-2108-563b-9dab-b24b8ef5aa04"}, {"name": "杜弘寿", "aliases": ["杜弘壽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杜弘寿是王都部下的龙泉镇将。《新五代史》记他率军迎接契丹被俘，表示不肯背弃王氏，随后被杀。", "biography": null, "status": "draft", "id": "93162875-8d0c-5759-8ec8-d18997552edf"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "亲信", "description": "孔循受到安重诲信任。关系限定在本段共事与婚议的语境，不推永久同盟或固定上下级。", "status": "draft", "id": "cf067a50-df23-51b2-9962-a86481c1e7e7", "person_a": "cbc4feeb-706c-5478-8f90-6130e12ed543", "person_b": "ce1aed16-1e3c-550a-954b-f37ff4743d0c"}, {"relation_type": "亲信", "description": "和昭训是王都的亲信，曾劝王都谋求自保。原文“腹心”是受信任的属人，不是血亲，起止年月未载。", "status": "draft", "id": "38a6ce57-9472-5ae2-9c43-a20eb5826289", "person_a": "397478dd-f587-584b-90e5-3ff921948933", "person_b": "e990d522-e16a-5709-b3a3-fd6ccf95796b"}, {"relation_type": "六军使", "description": "袁诠在此段楚国军务中任马殷的六军使。记录本段任职，不反推任用起年或永久从属。", "status": "draft", "id": "42270b93-4c08-58ef-9ead-83fbf4d7400c", "person_a": "7d2cfb56-e9ac-5d69-80a4-c6e4af7c4d87", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "六军副使", "description": "王环在此段楚国军务中任马殷的六军副使。记录本段任职，不反推任用起年或永久从属。", "status": "draft", "id": "5a35f18b-f50f-5af2-8eaa-001ab7cc7a1a", "person_a": "6a6bb82a-8b0a-5492-a34a-772c01702860", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "监军", "description": "马希瞻在此段楚国水军行动中任马殷的监军。这里只记录任职，未据姓氏新增父子关系。", "status": "draft", "id": "484abbbd-3e7c-5086-aef7-2fae75841955", "person_a": "3df1a631-6ec2-59fc-b5c8-028ed5fefc6c", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "右丞相", "description": "许德勋在楚国任马殷的右丞相，此段受命指挥水军。任职起止年月未载。", "status": "draft", "id": "5278294e-4555-5dfd-8881-70ac0c7694b3", "person_a": "22c59d0c-1661-5bcc-b43e-84d97c1ecda4", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "属官", "description": "冯赟获任北都副留守，辅佐河东节度使、北都留守李从荣。关系限定在此次任职，不推私人盟誓或终身从属。", "status": "draft", "id": "f2e12fad-88a1-52df-9ad0-b829cb2bf2a4", "person_a": "2fecae8c-9a43-5dd2-bc47-db5c33c3188f", "person_b": "87795090-8fc2-547d-a3a4-329b992a57f3"}, {"relation_type": "属官", "description": "杨思权获任步军都指挥使，辅佐李从荣。关系限定在此次任职，不以其后来言论推已经发动叛乱。", "status": "draft", "id": "9903cd73-0fc0-57ee-aee6-8ad239843b41", "person_a": "dd63d02d-f660-5b3d-a323-acb6a441dbc3", "person_b": "87795090-8fc2-547d-a3a4-329b992a57f3"}, {"relation_type": "牙将", "description": "武从谏是赵德钧的牙将，本段受命率骑截击契丹败军。具体任职起止未载。", "status": "draft", "id": "6559546a-ed4e-52b5-bf18-fa6f41db0ca0", "person_a": "6f5a738d-7e2a-5b28-8a99-c599caa1e5c7", "person_b": "cfda6466-f577-56a2-8851-65b57edb7d3e"}, {"relation_type": "部将", "description": "《新五代史》记郑季璘为王都部下的指挥使，受命迎接契丹。这是定州战役阶段的任职，不推永久同盟。", "status": "draft", "id": "8e3762cf-eaaa-5dfa-ba7c-4225ecc7447a", "person_a": "eee27a95-2108-563b-9dab-b24b8ef5aa04", "person_b": "e990d522-e16a-5709-b3a3-fd6ccf95796b"}, {"relation_type": "部将", "description": "《新五代史》记杜弘寿为王都部下的龙泉镇将，受命迎接契丹。后文受恩两世是其自述，不另造亲缘。", "status": "draft", "id": "989e9b36-0829-56bf-ad4a-9a33147efb8c", "person_a": "93162875-8d0c-5759-8ec8-d18997552edf", "person_b": "e990d522-e16a-5709-b3a3-fd6ccf95796b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

